/* @autogenerated */
import { computed, effect, inject, Injector, ResourceRef, Signal, signal, untracked } from '@angular/core';
import { rxResource, toSignal } from '@angular/core/rxjs-interop';
import {
  catchError,
  EMPTY,
  filter,
  finalize,
  map,
  mergeMap,
  Observable,
  of,
  Subscription,
  take,
  tap,
  throwError,
} from 'rxjs';
import { v4 as uuidv4 } from 'uuid';
import { handledErrors } from '@shared/context/observability/error.service';
import { EditConflictError } from '@shared/toolkit/edit-conflict/edit-conflict.model';
import { Acl } from '../acl/acl.model';
import {
  DownloadBlob,
  EntityMetadata,
  RepositoryProvider,
  Slide,
  UploadProgress,
} from './provider/repository-provider.interface';
import { Shift, Tick, UpdateOptions } from './repository.model';
import { CacheResource } from './cache-resource';
import { RepositoryCache, RepositoryStore } from './repository-store.service';

export interface RepositoryMetadata<T, F> {
  key: string;
  name: string;
  provider: RepositoryProvider<T, F>;
  /** Metadatos de la entidad (campos fecha, sensibles, de visualización…). */
  entity?: EntityMetadata;
  /** Vida (ms) de la caché de esta entidad; sin ella se usa `data.cache-ttl`. */
  ttl?: number;
  /** Metadatos del repositorio al que apunta la referencia `name`, o `null` si no la hay. */
  reference?: (name: string) => RepositoryMetadata<any, any> | null;
}

/** ACL todavía sin cargar: no concede nada. */
const NO_ACL: Acl = {};

/** Estado HTTP con el que el backend rechaza un guardado con una `version` que ya no es la vigente. */
const PRECONDITION_FAILED = 412;

/** Valor de una referencia sin `$ref`. */
const NO_REFERENCE: Signal<undefined> = signal(undefined).asReadonly();

export class RepositoryService<T, F> {
  private readonly cache: RepositoryCache;
  private readonly ttl: () => number;

  constructor(
    private readonly meta: RepositoryMetadata<T, F>,
    private readonly store: RepositoryStore,
  ) {
    this.cache = store.of(meta.name);
    this.ttl = () => store.ttl(meta.ttl);
  }

  generateComb(): string {
    const guid = uuidv4().split('-');
    const timestamp = Date.now().toString(16).slice(-12); // tomar los últimos 12 caracteres del timestamp en hexadecimal

    // Reemplazar la última parte del UUID con el timestamp
    guid[2] = timestamp.slice(0, 4);
    guid[3] = 'a' + timestamp.slice(4, 7);
    guid[4] = timestamp.slice(7, 11) + guid[4].slice(4, 12);
    return guid.join('-');
  }

  /**
   * ACL genérico (`fetch(null)`) y del elemento (`fetch(key)`). Mientras una parte no se ha cargado
   * vale `{}`, que no concede nada. Requiere contexto de inyección.
   */
  acl(): Tick<{ generic: Acl; specific: Acl }, string | null> {
    const injector = inject(Injector);
    const generic = ticker(injector, (_: null) => this.checkAcl(null));
    const specific = ticker(injector, (key: string) => this.checkAcl(key));
    const value = computed(() => {
      const g = generic.value();
      const s = specific.value();
      return g === undefined && s === undefined ? undefined : { generic: g ?? NO_ACL, specific: s ?? NO_ACL };
    });
    return asTick(
      injector,
      value,
      computed(() => generic.searching() || specific.searching()),
      (key: string | null) => {
        if (key) {
          specific.fetch(key);
        } else {
          generic.fetch(null);
          specific.reset();
        }
      },
      () => {
        generic.reset();
        specific.reset();
      },
    );
  }

  checkAcl(key: string | null): Observable<Acl> {
    const acl = this.meta.provider.acl;
    if (!acl) {
      return of({ allAllowed: true });
    }
    return new Observable<Acl>((observer) => {
      const entries = this.cache.resourceAclData;
      const theKey = key || '--';
      if (!entries[theKey]) {
        entries[theKey] = { cache: new CacheResource<Acl>(entries, theKey, this.ttl), observers: 0 };
      }
      const entry = entries[theKey].cache;
      if (entry.isExpired()) {
        entry.markWaiting();
        // Fire-and-forget: updates shared cache independently of observer lifecycle.
        acl
          .call(this.meta.provider, key)
          .pipe(take(1))
          .subscribe((value) => entry.touch(value));
      }
      const suscrip = entry
        .observable()
        .pipe(filter((v) => v !== undefined))
        .subscribe((value) => observer.next(value));
      return () => suscrip.unsubscribe();
    });
  }

  downloadFile(endpoint: string): Observable<DownloadBlob> {
    return this.meta.provider.downloadFile(endpoint);
  }

  storeFile(endpoint: string, name: string, file: File): Observable<UploadProgress> {
    return this.meta.provider.storeFile(endpoint, name, file);
  }

  add(item: T): Observable<T> {
    const key = this.itemKey(item);
    return this.meta.provider.add(this.toWire(item)).pipe(
      take(1),
      map((result) => this.mapItem(result)),
      tap((result) => {
        this.refreshAll();
        this.cacheItem(key).touch(result);
      }),
    );
  }

  deleteByKey(key: string): Observable<void> {
    return this.meta.provider.delete(key).pipe(
      take(1),
      tap(() => {
        this.refreshAll();
        this.cacheItem(key).remove();
      }),
    );
  }

  canDeleteSelection(): boolean {
    return !!this.meta.provider.deleteAllForQuery;
  }

  deleteSelection(query: F): Observable<any> {
    const call = this.meta.provider.deleteAllForQuery;
    if (!call) {
      throw new Error('Unable to make deleteSelection');
    }
    // El sondeo completa al terminar la tarea; si se abandona antes (se cierra el diálogo) también se refresca
    return call.call(this.meta.provider, query).pipe(finalize(() => this.refreshAfterBulk()));
  }

  /**
   * Guarda el elemento completo. Contrato con el backend (bloqueo optimista): el cuerpo lleva la `version` que se
   * leyó y, si ya no es la vigente, responde **412 Precondition Failed**, opcionalmente con la entidad actual en el
   * cuerpo. (Si más adelante se adopta `If-Match`/`ETag`, el 412 se trata igual.)
   *
   * Con `options.original`, el 412 no llega al aviso global: se obtiene el valor actual (del cuerpo del error o
   * releyéndolo sin caché), se actualiza la caché y se emite un `EditConflictError` con las tres versiones. Si la
   * relectura falla (404 porque se ha borrado, 403…) se emite ese error tal cual.
   */
  update(item: T, options: UpdateOptions<T> = {}): Observable<T> {
    const key = this.itemKey(item);
    const saved = this.meta.provider.update(key, this.toWire(item)).pipe(
      take(1),
      map((result) => this.mapItem(result)),
      tap((result) => {
        this.cacheItem(key, result);
      }),
    );
    const original = options.original;
    if (original === undefined) {
      return saved;
    }
    return saved.pipe(
      handledErrors([PRECONDITION_FAILED]),
      catchError((error) => {
        if (error?.status !== PRECONDITION_FAILED) {
          return throwError(() => error);
        }
        return this.currentAfterConflict(key, error.error).pipe(
          mergeMap((current) => throwError(() => new EditConflictError<T>({ original, sent: item, current }, error))),
        );
      }),
    );
  }

  /** Valor vigente tras un 412: el del cuerpo si tiene forma de entidad; si no, releído saltando la caché. */
  private currentAfterConflict(key: string, body: unknown): Observable<T> {
    const fromBody = body && typeof body === 'object' && this.itemKey(body as T) === key;
    const current = fromBody
      ? of(this.mapItem(body))
      : this.meta.provider.retrieve(key).pipe(
          take(1),
          map((value) => this.mapItem(value)),
          catchError((error) => {
            this.cache.resourceMap[key]?.cache.remove();
            return throwError(() => error);
          }),
        );
    return current.pipe(tap((value) => this.cacheItem(key, value)));
  }

  partialByKey(key: string, args: any, path?: string): Observable<T> {
    return this.meta.provider.patch(key, this.toWire(args), path).pipe(
      take(1),
      map((result) => this.mapItem(result)),
      tap((result) => {
        this.cacheItem(key, result);
      }),
    );
  }

  canUsePartialsByKey(): boolean {
    return !!this.meta.provider.patchAllForQuery;
  }

  partialBySelection(query: F, args: any, path?: string): Observable<any> {
    const call = this.meta.provider.patchAllForQuery;
    if (!call) {
      throw new Error('Unable to make partialBySelection');
    }
    return call
      .call(this.meta.provider, path || '', query, this.toWire(args))
      .pipe(finalize(() => this.refreshAfterBulk()));
  }

  values(query: F): Observable<T[]> {
    return this.list(query).pipe(map((slide) => slide?.content || []));
  }

  list(query: F): Observable<Slide<T>> {
    const paged = (query as any).cursor !== undefined || (query as any).since !== undefined;
    const listKey = JSON.stringify(query);
    const listMap = this.cache.listMap;
    return new Observable<Slide<T>>((observer) => {
      const suscrip = new Subscription();
      // If the list is shared, we could rehuse.
      if (!listMap[listKey]) {
        listMap[listKey] = {
          observers: 0,
          query: query,
          cache: new CacheResource<Slide<T>>(listMap, listKey, this.ttl),
        };
      }
      // Load shares store query
      if (listMap[listKey].cache.isExpired()) {
        listMap[listKey].cache.markWaiting();
        // The provider fetch is fire-and-forget: it updates the shared cache regardless
        // of who triggered it or who unsubscribes. This prevents take(1) in refreshAll()
        // from cancelling an in-flight HTTP request before the cache can be populated.
        this.meta.provider
          .list(query)
          .pipe(take(1))
          .subscribe((data) => {
            // Without next params the following request would repeat the same query.
            const hasNext = !!data.hasNext && Object.keys(data.next ?? {}).length > 0;
            const result: Slide<T> = {
              hasNext: hasNext,
              next: data.next,
              content: [],
            };
            if (paged && data.content.length === 0) {
              delete listMap[listKey];
            }
            data.content.forEach((row: any) => {
              const key = this.itemKey(row);
              const item = this.mapItem(row);
              const stored = this.cacheItem(key, item);
              result.content.push(item);
              suscrip.add(
                stored.observable().subscribe((ch) => {
                  // Always read the current list cache value to avoid stale closures
                  // after refreshAll() replaces the list with a newer version.
                  if (!listMap[listKey]) return;
                  const currentList = listMap[listKey].cache.currentValue();
                  if (!currentList) return;
                  const itemIndex = currentList.content.findIndex((row: any) => this.itemKey(row) === key);
                  if (itemIndex === -1) return;
                  const prev = JSON.stringify(currentList.content[itemIndex]);
                  const curr = JSON.stringify(ch);
                  if (prev !== curr) {
                    const copy = { ...currentList };
                    copy.content = [...currentList.content];
                    copy.content[itemIndex] = ch!;
                    listMap[listKey].cache.touch(copy);
                  }
                }),
              );
            });
            if (!paged || data.content.length !== 0) {
              listMap[listKey].cache.touch(result);
            } else {
              observer.next(result);
            }
          });
      }
      if (listMap[listKey]) {
        suscrip.add(
          listMap[listKey].cache.observable().subscribe((val) => {
            if (val !== undefined) {
              observer.next(val);
            }
          }),
        );
      }
      return () => suscrip.unsubscribe();
    });
  }

  retrieve(key: string): Observable<T | undefined> {
    return this.cached(key, this.meta.provider.retrieve(key).pipe(map((item) => this.mapItem(item))));
  }

  /**
   * Lista paginada: `fetch(query)` carga la primera página y `next()` añade la siguiente.
   * Cada referencia de `includes` se expone como un `Signal` con el elemento referenciado.
   * Requiere contexto de inyección.
   */
  public projections(includes: string[] = []): Shift<any[], F> {
    const injector = inject(Injector);
    const project = this.projector(includes, injector);
    const pages = signal<ResourceRef<Slide<T> | undefined>[]>([]);
    // Filas que se siguen mostrando mientras llega la primera página de una consulta nueva
    const stale = signal<T[] | undefined>(undefined);
    let current: F | undefined;

    // fetch() y next() se suelen llamar desde un effect: el recurso de cada página se crea fuera de él
    const page = (query: F) =>
      untracked(() => rxResource({ params: () => query, stream: ({ params }) => this.list(params), injector }));
    const rows = computed(() => {
      const all = pages();
      if (!all.length) {
        return undefined;
      }
      if (!all[0].hasValue()) {
        return all[0].isLoading() ? stale() : undefined;
      }
      return all.flatMap((p) => (p.hasValue() ? p.value().content : []));
    });
    const load = (query: F) => {
      current = query;
      untracked(pages).forEach((p) => p.destroy());
      pages.set([page(query)]);
    };

    const value = computed(() => rows()?.map(project));
    const shift: Shift<any[], F> = Object.assign(value, {
      searching: computed(() => pages().some((p) => p.isLoading())),
      fetch: (query: F) => {
        stale.set(untracked(rows));
        load(query);
        return shift;
      },
      reset: () => {
        stale.set(undefined);
        if (current === undefined) {
          untracked(pages).forEach((p) => p.destroy());
          pages.set([]);
        } else {
          load(current);
        }
        return shift;
      },
      next: () => {
        const last = untracked(pages).at(-1);
        // Mientras la última página carga no se sabe cuál es la siguiente: se ignora
        if (current !== undefined && last && !last.isLoading() && last.hasValue() && last.value().hasNext) {
          const query: F = { ...current, ...last.value().next };
          pages.update((all) => [...all, page(query)]);
        }
        return shift;
      },
      subscribe: (callback: (value: any[] | undefined) => void) => watch(injector, value, callback),
    });
    return shift;
  }

  /**
   * Un elemento por clave. Cada referencia de `includes` se expone como un `Signal` con el elemento
   * referenciado. Requiere contexto de inyección.
   */
  public projection(includes: string[] = []): Tick<any, string> {
    const injector = inject(Injector);
    const project = this.projector(includes, injector);
    const item = ticker(injector, (key: string) => this.retrieve(key));
    const value = computed(() => {
      const current = item.value();
      return current === undefined ? undefined : project(current);
    });
    return asTick(injector, value, item.searching, item.fetch, item.reset);
  }

  private refreshAfterBulk() {
    this.refreshAll();
    this.evictItems();
  }

  private refreshAll() {
    Object.values(this.cache.listMap).forEach((ll) => {
      ll.cache.evict();
      this.list(ll.query).pipe(take(1)).subscribe();
    });
  }

  private evictItems() {
    Object.values(this.cache.resourceMap).forEach((entry) => {
      entry.cache.remove();
    });
  }

  private itemKey(item: T): string {
    return (item as any)[this.meta.key];
  }

  /** Convierte a `Date` los campos que los metadatos declaran como fecha. */
  private mapItem(item: any): T {
    const entity = this.meta.entity;
    if (!item || typeof item !== 'object' || !(entity?.dates?.length || entity?.datetimes?.length)) {
      return item;
    }
    const copy = { ...item };
    entity.datetimes?.forEach((field) => {
      copy[field] = toDate(copy[field], parseDateTime);
    });
    entity.dates?.forEach((field) => {
      copy[field] = toDate(copy[field], parseLocalDate);
    });
    return copy;
  }

  /** Los campos `date` viajan como `YYYY-MM-DD`; los `datetime` ya se serializan en ISO-8601. */
  private toWire(item: any): any {
    const dates = this.meta.entity?.dates;
    if (!item || typeof item !== 'object' || !dates?.length) {
      return item;
    }
    const copy = { ...item };
    dates.forEach((field) => {
      if (copy[field] instanceof Date) {
        copy[field] = formatLocalDate(copy[field]);
      }
    });
    return copy;
  }

  private cached(key: string, obs: Observable<T>) {
    return new Observable<T>((observer) => {
      const suscrip = new Subscription();
      const stored = this.cacheItem(key);
      if (stored.isExpired()) {
        suscrip.add(stored.wait(obs));
      }
      suscrip.add(
        stored
          .observable()
          .pipe(filter((val) => val !== undefined))
          .subscribe((val) => {
            observer.next(val);
          }),
      );
      return () => suscrip.unsubscribe();
    });
  }

  private cacheItem(key: string, item?: T): CacheResource<T> {
    const resourceMap = this.cache.resourceMap;
    let entry = resourceMap[key];
    if (!entry) {
      entry = {
        observers: 0,
        cache: new CacheResource<T>(resourceMap, key, this.ttl, item === null ? undefined : item),
      };
      resourceMap[key] = entry;
    } else if (item) {
      entry.cache.touch(item);
    }
    return entry.cache;
  }

  /**
   * Copia superficial del elemento con cada referencia de `includes` sustituida por un `Signal` del
   * elemento referenciado. Las copias conservan los `Date`. Cada referencia se carga una sola vez.
   */
  private projector(includes: string[], injector: Injector): (item: any) => any {
    const reference = this.meta.reference;
    if (!includes.length || !reference) {
      return (item) => item;
    }
    const loaded = new Map<string, Signal<any>>();
    const load = (include: string, ref: string) =>
      untracked(() => {
        const meta = reference(include);
        if (!meta) {
          throw new Error('There is no ref repository for ' + include);
        }
        const retrieved = new RepositoryService<any, any>(meta, this.store).retrieve(ref).pipe(
          // El ClientService ya ha notificado el error: la referencia queda sin valor
          catchError(() => EMPTY),
        );
        return toSignal(retrieved, { injector });
      });
    return (item) => {
      const copy = { ...item };
      includes.forEach((include) => {
        const ref: string | undefined = item?.[include]?.['$ref'];
        if (!ref) {
          copy[include] = NO_REFERENCE;
          return;
        }
        const id = include + '\u0000' + ref;
        if (!loaded.has(id)) {
          loaded.set(id, load(include, ref));
        }
        copy[include] = loaded.get(id);
      });
      return copy;
    };
  }
}

interface Ticker<K, V> {
  value: Signal<V | undefined>;
  searching: Signal<boolean>;
  fetch(key: K): void;
  reset(): void;
}

/**
 * Carga por clave sobre `rxResource`. Mientras carga una clave nueva conserva el valor anterior,
 * para no parpadear entre consultas.
 */
function ticker<K, V>(injector: Injector, load: (key: K) => Observable<V>): Ticker<K, V> {
  // Un objeto nuevo en cada fetch: repetir la misma clave también vuelve a consultar
  const request = signal<{ key: K } | undefined>(undefined);
  const stale = signal<V | undefined>(undefined);
  const resource = rxResource({ params: () => request(), stream: ({ params }) => load(params.key), injector });
  const value = computed(() => {
    if (resource.hasValue()) {
      return resource.value();
    }
    return resource.isLoading() ? stale() : undefined;
  });
  return {
    value,
    searching: resource.isLoading,
    fetch: (key: K) => {
      stale.set(untracked(value));
      request.set({ key });
    },
    reset: () => {
      stale.set(undefined);
      request.set(undefined);
    },
  };
}

function asTick<V, K>(
  injector: Injector,
  value: Signal<V | undefined>,
  searching: Signal<boolean>,
  fetch: (key: K) => void,
  reset: () => void,
): Tick<V, K> {
  const tick: Tick<V, K> = Object.assign(value, {
    searching,
    fetch: (key: K) => {
      fetch(key);
      return tick;
    },
    reset: () => {
      reset();
      return tick;
    },
    subscribe: (callback: (value: V | undefined) => void) => watch(injector, value, callback),
  });
  return tick;
}

/** Llama a `callback` con el valor actual y con cada cambio, mientras viva `injector`. */
function watch<V>(injector: Injector, value: Signal<V>, callback: (value: V) => void): void {
  untracked(() =>
    effect(
      () => {
        const current = value();
        untracked(() => callback(current));
      },
      { injector },
    ),
  );
}

function toDate(value: unknown, parse: (value: string) => Date): unknown {
  if (typeof value !== 'string' || !value) {
    return value;
  }
  const date = parse(value);
  return isNaN(date.getTime()) ? value : date;
}

function parseDateTime(value: string): Date {
  return new Date(value);
}

/** `YYYY-MM-DD` a medianoche local: `new Date('YYYY-MM-DD')` sería medianoche UTC y cambiaría de día. */
function parseLocalDate(value: string): Date {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  return match ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3])) : new Date(value);
}

function formatLocalDate(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}
